// ── Inietta secrets e normalizza il body del webhook ─────────────────────
const supabaseUrl = "YOUR_SUPABASE_URL";
const supabaseKey = "YOUR_SUPABASE_SERVICE_ROLE_KEY";
const openaiKey   = "YOUR_OPENAI_API_KEY";

const body = $input.first().json.body || $input.first().json;

// Campi attesi dal payload v5: { userId, documentId, docType, jobDescription, templateId, requestedAt }
return [{ json: { supabaseUrl, supabaseKey, openaiKey, ...body } }];

// ── Legge dati dai nodi precedenti ───────────────────────────────────────
const cfg       = $('⚙️ Config').first().json;
const profileArr = $('🗄 Fetch Profile').first().json;
const profile   = Array.isArray(profileArr) ? profileArr[0] : profileArr;
const authUser  = $('👤 Fetch Auth User').first().json;
const experiences = $('🗄 Fetch Experiences').all().map(item => item.json);

const { userId, docType, jobDescription, documentId, templateId, openaiKey, supabaseUrl, supabaseKey } = cfg;
const email = authUser?.email || null;

// ── Formatta le esperienze come testo leggibile per l'AI ──────────────────
function formatExp(e) {
  const range = e.is_current
    ? `${e.start_date || '?'} – Presente`
    : `${e.start_date || '?'} – ${e.end_date || '?'}`;
  const skills = [...(e.skills || []), ...(e.tags || [])].join(', ');
  return `[${(e.type || 'work').toUpperCase()}] ${e.title} @ ${e.organization || 'N/A'} (${range})
Descrizione: ${(e.description || '(nessuna)').slice(0, 500)}
Competenze: ${skills || 'N/A'}`;
}

const expText = experiences.length === 0
  ? '(Nessuna esperienza disponibile)'
  : experiences.map(formatExp).join('\n\n');

// ── Design-Aware: tono di voce in base al templateId ─────────────────────
const toneMap = {
  creative: `STILE CREATIVE – Tono persuasivo, narrativo e dinamico.
Valorizza le soft skills, l'impatto personale e la crescita professionale.
Le descrizioni devono essere coinvolgenti ed evocative, come se raccontassero una storia.
Usa verbi attivi, evita elenchi aridi.`,
  minimal: `STILE MINIMAL – Tono formale, asciutto e conciso.
Privilegia risultati misurabili, keyword ATS e frasi brevi.
Zero aggettivi superflui. Struttura bullet-point diretta e scansionabile.`,
  modern: `STILE MODERN – Tono professionale ed equilibrato.
Valorizza competenze tecniche e risultati concreti con un linguaggio diretto ma non arido.
Bilanciare precisione tecnica e leggibilita'.`
};
const toneInstructions = toneMap[templateId] || toneMap.modern;

// ── System Prompt ─────────────────────────────────────────────────────────
const systemPrompt = `Sei un esperto career coach italiano specializzato in CV ATS-friendly.

${toneInstructions}

REGOLE CRITICHE E ASSOLUTE ANTI-ALLUCINAZIONE:
- DEVI basarti ESCLUSIVAMENTE sui dati indicati in "ESPERIENZE DEL CANDIDATO".
- E' SEVERAMENTE VIETATO inventare esperienze lavorative, aziende, scuole, lauree, certificazioni o date.
- Usa SOLO i titoli, i ruoli e le competenze forniti.
- Se il candidato ha poca esperienza pertinente con la Job Description, formula una descrizione adatta partendo UNICAMENTE dalle vere esperienze fornite. Non aggiungere MAI ruoli o lauree inesistenti come "Laurea in Informatica" se non presenti.
- Le "hard skill" estratte da te devono provenire principalmente dalle competenze/tags presenti nelle esperienze fornite e poi matchate con la JD.

IL TUO COMPITO:
1. Seleziona le esperienze piu' rilevanti per la Job Description:
   - Max 4 voci tra type "work" e "project"
   - Includi TUTTE le voci di type "education" disponibili
   - Includi TUTTE le voci di type "certification" disponibili
2. Per ogni voce selezionata, riscrivi la descrizione ottimizzata per la JD (2-4 frasi, keyword della JD, risultati concreti).
3. Genera un profile_summary di 3-4 righe tarato sullo stile richiesto.
4. Estrai una lista di hard skill rilevanti per la JD (max 12 voci).
5. Restituisci SOLO JSON valido. Nessun markdown. Nessun testo al di fuori del JSON.

STRUTTURA JSON OBBLIGATORIA – rispetta ESATTAMENTE questi nomi di campo:
{
  "profile_summary": "stringa",
  "experiences": [
    { "title": "str", "organization": "str", "period": "MMM YYYY - MMM YYYY o Presente", "description": "str", "tags": ["skill"] }
  ],
  "education": [
    { "title": "str", "organization": "str", "period": "str", "description": "str o null", "tags": [] }
  ],
  "certifications": [
    { "title": "str", "organization": "str", "period": "str", "description": "str o null", "tags": [] }
  ],
  "skills": ["skill1", "skill2"]
}`;

// ── User Prompt ───────────────────────────────────────────────────────────
const userPrompt = `JOB DESCRIPTION:
${jobDescription}

ESPERIENZE DEL CANDIDATO:
${expText}

Restituisci il JSON strutturato.`;

return [{ json: {
  userId, docType, jobDescription, documentId,
  templateId, openaiKey, supabaseUrl, supabaseKey,
  profile, email,
  systemPrompt, userPrompt
} }];

// ── Assembla N8nGenerationResult: AI output + dati statici (contact, languages) ──
const buildData = $('🧠 Build AI Prompt').first().json;
const aiRaw = $input.first().json.choices[0].message.content;

// 1. Parsa il JSON restituito dall'AI
let aiData;
try {
  const cleaned = aiRaw.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
  aiData = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI output non e\' JSON valido: ' + aiRaw.slice(0, 300));
}

const { profile, email, userId, documentId, supabaseUrl, supabaseKey } = buildData;

// 2. Blocco contatto STATICO — non passa per l'AI
const fullName  = (profile?.full_name || '').trim();
const nameParts = fullName.split(' ').filter(Boolean);
const firstName = nameParts[0] || '';
const lastName  = nameParts.slice(1).join(' ') || '';
const initials  = nameParts.map(p => p[0] || '').join('').toUpperCase().slice(0, 2);

const contact = {
  full_name:     fullName,
  first_name:    firstName,
  last_name:     lastName,
  initials:      initials,
  headline:      profile?.headline      || null,
  city:          profile?.city          || null,
  phone:         profile?.phone         || null,
  email:         email                  || null,
  linkedin_url:  profile?.linkedin_url  || null,
  portfolio_url: profile?.portfolio_url || null,
  avatar_url:    profile?.avatar_url    || null
};

// 3. Lingue STATICHE — zero AI, derivate da native_language + certificazioni linguistiche
const languages = [];

// 3a. Lingua madre (inserita manualmente dall'utente nel profilo)
const nativeLang = profile?.native_language;
if (nativeLang) {
  languages.push({ name: nativeLang, level: 'Madrelingua', proficiency: 100 });
}

// 3b. Lingue da certificazioni (keyword matching sul titolo/organizzazione)
const allExperiences = $('🗄 Fetch Experiences').all().map(item => item.json);

const langKeywords = [
  'ielts', 'toefl', 'cambridge', 'delf', 'dalf', 'goethe', 'dele',
  'hsk', 'jlpt', 'tef', 'tcf', 'first certificate', 'advanced english',
  'inglese', 'francese', 'tedesco', 'spagnolo', 'portoghese',
  'cinese', 'giapponese', 'russo', 'arabo'
];
const proficiencyMap = { A1: 15, A2: 28, B1: 45, B2: 62, C1: 80, C2: 95 };

const langCerts = allExperiences.filter(e =>
  e.type === 'certification' &&
  langKeywords.some(kw =>
    (e.title + ' ' + (e.organization || '')).toLowerCase().includes(kw)
  )
);

for (const cert of langCerts) {
  const levelMatch = cert.title.match(/\b(A1|A2|B1|B2|C1|C2)\b/i);
  const level = levelMatch ? levelMatch[1].toUpperCase() : null;
  const proficiency = level ? (proficiencyMap[level] || 60) : 60;
  // Usa l'organizzazione come nome lingua se disponibile (es. 'Inglese'), altrimenti il titolo
  const name = cert.organization || cert.title;
  languages.push({ name, level: level || cert.title, proficiency });
}

// 4. Helper: normalizza ogni voce esperienza/education/certification
const mapItem = e => ({
  title:        e.title        || '',
  organization: e.organization || '',
  period:       e.period       || '',
  description:  e.description  || '',
  tags:         Array.isArray(e.tags) ? e.tags : []
});

// 5. Oggetto finale N8nGenerationResult
const result = {
  contact,
  profile_summary: aiData.profile_summary || '',
  experiences:     (aiData.experiences    || []).map(mapItem),
  education:       (aiData.education      || []).map(mapItem),
  certifications:  (aiData.certifications || []).map(mapItem),
  skills:          aiData.skills          || [],
  languages
};

return [{ json: { result, userId, documentId, supabaseUrl, supabaseKey } }];
